/**
 * Tests for Hebrew date computation.
 *
 * Expected strings below are literals verified against hebcal.com, not
 * generated by calling computeHebrewDate itself:
 *   - 2000-01-01 -> 23 Tevet 5760 (leap year)
 *   - 2001-09-11 -> 23 Elul 5761
 *   - 2024-03-24 -> Purim, 14 Adar II 5784 (leap year, Adar II)
 */

import { computeHebrewDate, hebrewDateFor } from '~/lib/hebrew-date'

describe('computeHebrewDate', () => {
  it('computes 1 January 2000 as 23 Tevet 5760', () => {
    expect(computeHebrewDate(new Date(Date.UTC(2000, 0, 1)))).toBe('כ״ג בטבת תש״ס')
  })

  it('computes 11 September 2001 as 23 Elul 5761', () => {
    expect(computeHebrewDate(new Date(Date.UTC(2001, 8, 11)))).toBe('כ״ג באלול תשס״א')
  })

  it('computes 24 March 2024 (Purim) as 14 Adar II 5784, a leap year', () => {
    expect(computeHebrewDate(new Date(Date.UTC(2024, 2, 24)))).toBe('י״ד באדר ב׳ תשפ״ד')
  })
})

describe('hebrewDateFor', () => {
  it('returns null when the event has no date and no override', () => {
    expect(hebrewDateFor({ date: null, hebrewDateOverride: null })).toBeNull()
  })

  it('returns the computed value when there is no override', () => {
    expect(
      hebrewDateFor({ date: new Date(Date.UTC(2000, 0, 1)), hebrewDateOverride: null })
    ).toBe('כ״ג בטבת תש״ס')
  })

  it('prefers the override over the computed value', () => {
    expect(
      hebrewDateFor({
        date: new Date(Date.UTC(2000, 0, 1)),
        hebrewDateOverride: 'כ״ג בטבת תש״ס (ידני)',
      })
    ).toBe('כ״ג בטבת תש״ס (ידני)')
  })

  it('falls back to the computed value when the override is blank', () => {
    expect(
      hebrewDateFor({ date: new Date(Date.UTC(2000, 0, 1)), hebrewDateOverride: '   ' })
    ).toBe('כ״ג בטבת תש״ס')
  })
})
